import copy,json,unittest
from pathlib import Path
from beat import elect
F=json.loads((Path(__file__).parent/'fixture.json').read_text())
class Tests(unittest.TestCase):
 def setUp(self): self.o=copy.deepcopy(F['objects']);self.e=copy.deepcopy(F['events']);self.p=copy.deepcopy(F['policy'])
 def r(self):return elect(self.o,self.e,self.p)
 def test_width(self):self.assertEqual(len(self.r()['selected']),2)
 def test_budget(self):self.assertEqual(self.r()['budget']['remaining_above_reserve'],0)
 def test_x2_not_reboot(self):self.assertEqual(self.r()['selected'][0]['action'],'INSPECT_READ_ONLY')
 def test_gap_first_class(self):self.assertEqual(self.r()['selected'][1]['obj'],'syn:gap:ack')
 def test_dormant_research(self):self.assertIn('WIDTH_CAP',[x['why'] for x in self.r()['held']])
 def test_inferred_health_never_alive(self):self.assertIn('LEASE_STALE_RUNTIME_UNKNOWN',[x['state'] for x in self.r()['observed']])
 def test_private_rejected(self):self.assertIn('AUTHORITY_OR_PRIVACY',[x['why'] for x in self.r()['held']])
 def test_no_external_effects(self):self.assertTrue(all(x==0 for x in self.r()['effects'].values()))
 def test_digest_determinism(self):self.assertEqual(self.r()['receipt_digest'],self.r()['receipt_digest'])
 def test_event_order(self):a=self.r();self.e.reverse();self.assertEqual(a['receipt_digest'],self.r()['receipt_digest'])
 def test_replay_deduped(self):self.e.append(copy.deepcopy(self.e[0]));self.assertIn('REPLAY_DEDUPED',[x['state'] for x in self.r()['observed']])
 def test_id_collision(self):e=copy.deepcopy(self.e[0]);e['cost']=2;self.e.append(e);self.assertIn('ID_COLLISION_NO_DISPATCH',[x['why'] for x in self.r()['held']]);self.assertNotIn('syn:x2:ux',[x['obj'] for x in self.r()['selected']])
 def test_explicit_stop(self):self.e.append({'seq':7,'eid':'e7','obj':'syn:x2:ux','kind':'STOP','privacy':'PUBLIC','scope':'READ_ONLY','evidence':'SYNTHETIC_VERIFIED'});self.assertNotIn('syn:x2:ux',[x['obj'] for x in self.r()['selected']])
 def test_untrusted_stop_ignored(self):self.e.append({'seq':7,'eid':'e7','obj':'syn:x2:ux','kind':'STOP','privacy':'PRIVATE','scope':'READ_ONLY','evidence':'SYNTHETIC_VERIFIED'});self.assertIn('syn:x2:ux',[x['obj'] for x in self.r()['selected']])
 def test_unqualified_evidence(self):self.e[0]['evidence']='GUESSED';self.assertIn('UNVERIFIED',[x['why'] for x in self.r()['held']])
 def test_forbidden_effect(self):self.e[0]['scope']='EXECUTE';self.assertIn('AUTHORITY_OR_PRIVACY',[x['why'] for x in self.r()['held']])
 def test_depth(self):self.e[0]['depth']=3;self.assertIn('TURTLE_BUDGET',[x['why'] for x in self.r()['held']])
 def test_round(self):self.e[0]['round']=3;self.assertIn('TURTLE_BUDGET',[x['why'] for x in self.r()['held']])
 def test_budget_reserve_floor(self):self.p['budget']=2;self.assertEqual(self.r()['selected'],[])
 def test_zero_frontier(self):self.p['width']=0;self.assertEqual(self.r()['selected'],[])
 def test_no_events(self):self.e=[];self.assertEqual(self.r()['selected'],[]);self.assertEqual(self.r()['observed'],[])
 def test_no_material_delta(self):self.e[2]['new_hash']='synthetic-paper-v1';self.assertIn('NO_SOURCE_CHANGE',[x['state'] for x in self.r()['observed']])
 def test_symbolic_not_watts(self):self.e[3]['watts']=40;self.assertIn('HYPOTHESIS_NOT_WATTS',[x['why'] for x in self.r()['held']])
 def test_unknown_kind(self):self.e[0]['kind']='MATERIALIZE';self.assertIn('UNKNOWN_KIND',[x['why'] for x in self.r()['held']])
 def test_unknown_object(self):self.e[0]['obj']='missing';self.assertIn('UNKNOWN_OBJECT',[x['why'] for x in self.r()['held']])
 def test_duplicate_object_wave(self):self.e.append({'seq':7,'eid':'e7','obj':'syn:x2:ux','kind':'PRESSURE','privacy':'PUBLIC','scope':'READ_ONLY','evidence':'SYNTHETIC_VERIFIED'});self.assertIn('DUPLICATE_OBJECT_WAVE',[x['why'] for x in self.r()['held']])
 def test_public_router_rejects_matching_private_scope(self):self.e[5]['privacy']='PRIVATE';self.assertIn('AUTHORITY_OR_PRIVACY',[x['why'] for x in self.r()['held']])
 def test_source_change_requires_new_hash(self):self.e[2].pop('new_hash');self.assertIn('MISSING_SOURCE_HASH',[x['why'] for x in self.r()['held']])
 def test_source_not_mutated(self):a=copy.deepcopy(self.o);self.r();self.assertEqual(a,self.o)
 def test_fresh_lease(self):self.e[4]['last_tick']=48;self.assertIn('SYNTHETIC_LEASE_FRESH',[x['state'] for x in self.r()['observed']])
 def test_no_receiver_acceptance_inferred(self):self.assertNotIn('ACKNOWLEDGED',str(self.r()))
 def test_schema(self):self.assertEqual(self.r()['schema'],'CoAll.CoMetabolism.BeatShadow.R0A')
 def test_secret_no_public_leak(self):self.assertNotIn('synthetic-private-v1',str(self.r()))
 def test_unknown_zero_inference(self):self.assertTrue(all('DEAD' not in x['state'] for x in self.r()['observed']))
 def test_shares_no_authority(self):self.assertTrue(all(x['result']=='PROPOSAL_ONLY' for x in self.r()['selected']))
 def test_idempotent_zero_new_work(self):self.e=[];self.assertEqual(self.r()['budget']['remaining_above_reserve'],2)
if __name__=='__main__':unittest.main()
